//! Gold: `document_scope` is 1:1 with the live reference.
//!
//! `tests/fixtures/gold/document_scope_v1.json` was generated by
//! `scripts/gold_document_scope.py` — each case rendered into a real PDF and
//! read by the reference's own `read_scope`, with the volatile keys
//! (`source_path`, `document_sha256`) stripped. The front-page texts travel
//! in the gold so this replays identical input.
//!
//! The cases pin the traps the reader exists for: filename binding lies
//! (`GD32F4xx` naming six series, F403 not one of them), ST composite series
//! preserved verbatim, the PM0214 class trap, and — most of all — that an
//! unreadable page (`extraction_failed`) is never reported as
//! `scope_absent`.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    reason = "gold tests assert on their own fixtures"
)]

use std::path::PathBuf;

use dw_recon::read_scope;

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/document_scope_v1.json")
}

fn gold() -> serde_json::Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

#[test]
fn every_case_matches_the_live_reference() {
    let g = gold();
    let mut checked = 0;
    for case in g["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let pages: Vec<String> = case["pages"]
            .as_array()
            .unwrap()
            .iter()
            .map(|p| p.as_str().unwrap().to_string())
            .collect();
        let control = case["expected"]["control_token"].as_str();
        let mut ours = read_scope(&pages, control);
        ours.source_path = Some(format!("/{name}.pdf"));
        ours.document_sha256 = Some("f".repeat(64));
        let mut got = serde_json::to_value(&ours).unwrap();
        // The volatile keys are stripped from the gold.
        for k in ["source_path", "document_sha256"] {
            got.as_object_mut().unwrap().remove(k);
        }
        assert_eq!(
            got, case["expected"],
            "case {name} diverged from the reference"
        );
        checked += 1;
    }
    assert_eq!(checked, 10);
}

/// Negative controls — the fail-closed directions.
#[test]
fn negative_control_instrument_failure_is_not_absence() {
    // Zero text: an instrument failure, never "the vendor prints no scope".
    let row = read_scope(&["tiny".into()], None);
    assert_eq!(row.status, "extraction_failed");
    assert_eq!(
        row.extraction_failed_reason.as_deref(),
        Some("no_text_layer_on_front_matter")
    );
    assert_eq!(
        row.scope_absent, None,
        "absence is unpronounceable when unreadable"
    );
    // A cover that prints no scope: a first-class answer, and only then.
    let row = read_scope(
        &["Quick Start Guide\nSome Vendor Inc\nThis guide covers development kit setup for boards."
            .into()],
        None,
    );
    assert_eq!(row.status, "read_ok");
    assert_eq!(row.scope_absent, Some(true));
    assert_eq!(
        row.scope_absent_reason.as_deref(),
        Some("no_scope_statement_printed")
    );
    // Filename binding lies: F403 is named in the filename universe but is
    // NOT printed on the cover — it must not appear.
    let row = read_scope(
        &["GD32F4xx User Manual\nFor GD32F405xx and GD32F407xx microcontrollers.".into()],
        None,
    );
    assert!(!row.governs_series.iter().any(|s| s.contains("F403")));
    // Series tokens stay verbatim — never expanded.
    let row = read_scope(
        &["STM32 Datasheet\nhow to use the STM32F405xx/07xx microcontroller memory.".into()],
        None,
    );
    assert!(row.governs_series.contains(&"STM32F405xx/07xx".to_string()));
}
